import{z as l,x as s,o as i,c as B,q as e,j as _,D as t,d as n,s as m,S as o}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"LMM 漂移与测度变换","description":"","frontmatter":{"title":"LMM 漂移与测度变换","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lmm-drift-measure.md","filePath":"quant/lmm-drift-measure.md","lastUpdated":1791413859000}'),E={name:"quant/lmm-drift-measure.md"};function p(A,a,d,u,c,h){const r=s("Mermaid");return i(),B("div",null,[a[2]||(a[2]=e('<h1 id="lmm-漂移与测度变换" tabindex="-1">LMM 漂移与测度变换 <a class="header-anchor" href="#lmm-漂移与测度变换" aria-label="Permalink to &quot;LMM 漂移与测度变换&quot;">​</a></h1><div class="epigraph"><p>每个简单远期只在自己的支付日远期测度下是鞅；要在同一个概率空间里模拟整条曲线，就必须用计价物比把漂移写出来，而不能假定所有 $L_i$ 同时对数正态。</p><footer>—— Brace, Gątarek &amp; Musiela, The Market Model of Interest Rate Dynamics, Mathematical Finance, 1997</footer></div><p><a href="/quant/hw-two-factor">Hull-White 两因子</a>把 CMS 斜率与翼部留给了 LMM——本篇把 LMM 的账从根上算清。<a href="/quant/lmm">LMM</a> 已经把状态选成可观测的简单远期 \\(L_i\\)，并写出即期测度下的漂移公式。本篇把那条公式从「可以抄」变成「可以从计价物推出来」：换测度是 Girsanov，漂移是相对债券波动的点积，不是对瞬时 HJM 积分随便离散。Brace、Gątarek 与 Musiela（1997）的市场模型，核心不是对数正态本身，而是 tenor 结构下无套利漂移与 caplet 的 Black 公式在各自远期测度下对齐。Jamshidian 与 Miltersen–Sandmann–Sondermann 几乎同时给出等价构造。读懂漂移，才能判断预测器–校正器在改什么、终端测度与即期测度何时不可互换，以及 <a href="/quant/cms-replication">CMS 复制</a> 所用的年金测度如何嵌进同一套变换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>取定日期 \\(T_0\\lt \\cdots\\lt T_n\\)，\\(\\tau_i=T_{i+1}-T_i\\)，</p> \\[L_i(t)=\\frac{1}{\\tau_i}\\left(\\frac{P(t,T_i)}{P(t,T_{i+1})}-1\\right). \\]<p>\\(L_i\\) 是两只零息债的比，因而是可交易资产比。选计价物 \\(P(\\cdot,T_{i+1})\\)，对应 \\(T_{i+1}\\)-远期测度 \\(\\mathbb{Q}^{T_{i+1}}\\)，则 \\(L_i\\) 为鞅。对数正态假设立刻给出 Black caplet。问题是：账簿里有几十个重叠的 \\(L_i\\)，Monte Carlo 只能抽一个测度。若错误地让所有 \\(L_i\\) 在同一测度下都是无漂移对数正态，折现债券族不再是鞅，长端曲线会系统性漂掉，这是离散时间里最常见的「LMM 实现无套利失败」。</p><p><span class="marginnote">计价物可以翻译成「用哪件东西当尺子」：远期测度用「到期那天的零息债」当尺子，互换测度用「一串付款的年金」当尺子。换尺子不改变东西的价值，但改变它「看起来有没有漂移」——同一利率在这把尺子下是鞅，换一把尺子就必须补漂移项。</span></p><p>第二个问题是数值而不是理论。即期 LIBOR 测度的漂移含 \\(\\sum_j \\tau_j L_j/(1+\\tau_j L_j)\\)，状态依赖，欧拉离散有偏。预测器–校正器、对数欧拉、以及换到终端测度（只让最远端 \\(L_{n-1}\\) 无漂移）都是在改同一段 Girsanov 核的积分误差。不写清测度，就无法解释为什么换随机种子后面值变了、换终端测度后面值又变了。</p><h3 id="计价物定理给出的漂移核" tabindex="-1">计价物定理给出的漂移核 <a class="header-anchor" href="#计价物定理给出的漂移核" aria-label="Permalink to &quot;计价物定理给出的漂移核&quot;">​</a></h3><p>设计价物 \\(N\\) 与 \\(M\\) 的波动向量为 \\(\\nu^N,\\nu^M\\)（对同一套布朗）。Girsanov 说，从 \\(\\mathbb{Q}^M\\) 到 \\(\\mathbb{Q}^N\\)，</p> \\[\\mathrm{d}W^N = \\mathrm{d}W^M - \\bigl(\\nu^N-\\nu^M\\bigr)^\\top \\mathrm{d}t \\]<p>（符号随波动定义约定，实现必须与 Ito 公式一致）。资产 \\(X\\) 若在 \\(\\mathbb{Q}^M\\) 下波动为 \\(\\sigma^X\\)，则其在 \\(\\mathbb{Q}^N\\) 下的漂移等于 \\(\\sigma^X\\cdot(\\nu^N-\\nu^M)\\)。对 \\(L_i\\)，在 \\(\\mathbb{Q}^{T_{i+1}}\\) 下漂移为零；换到另一个远期测度 \\(\\mathbb{Q}^{T_{k+1}}\\)，漂移就是 \\(L_i\\) 的波动乘上 \\(P(\\cdot,T_{i+1})\\) 相对 \\(P(\\cdot,T_{k+1})\\) 的波动差。债券比的波动由中间那串 \\(L_j\\) 决定，于是出现因子 \\(\\tau_j L_j/(1+\\tau_j L_j)\\)：它正是 \\(\\partial \\log P(\\cdot,T_{j+1})/\\partial L_j\\) 一类载荷，不是经验权重。</p><p><span class="marginnote">把 LMM 理解成「HJM 的离散版」可以，但简单利率与瞬时远期的 Ito 对应带 \\(1+\\tau L\\) 分母。对 \\(f(t,T)\\) 做欧拉再换成 \\(L\\)，漂移条件会被离散破坏。实现必须对 \\(L_i\\) 直接积分 BGM 漂移。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\(T_{i+1}\\)-远期测度下，BGM 取</p> \\[\\mathrm{d}L_i(t)=\\sigma_i(t)L_i(t)\\,\\mathrm{d}W_t^{T_{i+1}}. \\]<p>即期 LIBOR 测度用滚动银行账户 \\(B_t\\)：在每个 \\(T_q\\) 把本金再投资一期，计价物在 \\((T_q,T_{q+1}]\\) 上与 \\(P(\\cdot,T_{q+1})\\) 成比例。对第一个未确定远期下标 \\(q(t)\\) 以及 \\(i\\ge q(t)\\)，</p> \\[\\mu_i(t)=\\sigma_i(t)\\sum_{j=q(t)}^{i}\\frac{\\tau_j L_j(t)}{1+\\tau_j L_j(t)}\\rho_{ij}(t)\\sigma_j(t), \\]\\[\\frac{\\mathrm{d}L_i}{L_i}=\\mu_i(t)\\,\\mathrm{d}t+\\sigma_i(t)\\,\\mathrm{d}W_t^{\\mathrm{spot}}. \\]<p>这是 Brace–Gątarek–Musiela 无套利条件的即期形式。终端测度 \\(\\mathbb{Q}^{T_n}\\) 让 \\(L_{n-1}\\) 为鞅，更近的 \\(L_i\\) 带负向累积漂移（相对即期公式符号相反的一段），模拟长到期 cap 有时方差更小。互换测度的计价物是年金 \\(A\\)，互换利率 \\(S\\) 为鞅，但 \\(S\\) 不是单个 \\(L_i\\)，<a href="/quant/cms-convexity">CMS</a> 支付又不在年金测度下结算，必须再换一次。</p><p><span class="marginnote">数字实例：取 \\(\\tau_j=0.25\\)（3 个月期）、\\(L_j=4\\%\\)，则 \\(\\tau_j L_j/(1+\\tau_j L_j)=0.01/1.01\\approx0.0099\\)，与 \\(\\tau_j L_j=0.01\\) 只差约 \\(1\\%\\)——低利率下两者几乎一样；但高利率或长期限时分母不可忽略，随手把分母写成 1 就会破坏无套利。</span></p><p>离散格式：对数欧拉</p> \\[\\log L_i(t+\\Delta)=\\log L_i(t)+\\bigl(\\mu_i-\\tfrac12\\sigma_i^2\\bigr)\\Delta+\\sigma_i\\sqrt{\\Delta}\\,Z \\]<p>里的 \\(\\mu_i\\) 若用左端点 \\(L(t)\\)，对长 tenor、大波动会系统性抬高或压低远端曲线。预测器–校正器先用左端点走一步得 \\(\\hat L\\)，再用 \\(\\tfrac12(\\mu(L)+\\mu(\\hat L))\\) 重做，把状态依赖漂移的一阶偏差压下去。相关矩阵必须正定；因子载荷 \\(\\sigma_i\\) 是向量时，\\(\\rho_{ij}\\sigma_i\\sigma_j\\) 应写成 \\(\\sigma_i\\cdot\\sigma_j\\)。</p><p><span class="marginnote">预测器–校正器可以类比「先估后修」的导航：先用当前位置粗算一步会到哪（预测），再在新位置重算漂移、取平均修正路线（校正）。漂移 \\(\\mu_i\\) 依赖利率水平本身，用老位置算一整步会系统性偏，修一次就把这个一阶偏差压掉。</span></p><h3 id="从债券比推到" tabindex="-1">从债券比推到 \\(\\tau L/(1+\\tau L)\\) <a class="header-anchor" href="#从债券比推到" aria-label="Permalink to &quot;从债券比推到 $\\tau L/(1+\\tau L)$&quot;">​</a></h3><p>固定 \\(k\\gt i\\)。乘积</p> \\[\\frac{P(t,T_i)}{P(t,T_{k+1})}=\\prod_{j=i}^{k}\\bigl(1+\\tau_j L_j(t)\\bigr) \\]<p>的对数微分给出 \\(P(\\cdot,T_i)\\) 相对 \\(P(\\cdot,T_{k+1})\\) 的波动，等于各段 \\(\\frac{\\tau_j L_j}{1+\\tau_j L_j}\\sigma_j\\) 之和（再加 \\(L_i\\) 自身那一项的组合）。把这段相对波动送进 Girsanov，就得到 \\(L_i\\) 在 \\(\\mathbb{Q}^{T_{k+1}}\\) 下的漂移。\\(k=i\\) 时相对波动为零，漂移为零，回到远期测度鞅。推导应在连续时间 Ito 下完成，再对模拟步做离散近似；不要在离散乘积上「加一个经验凸性」充作漂移。</p><p>多曲线时代贴现用 OIS、预测用期限 SOFR 或残存的 IBOR。BGM 公式仍对<strong>预测曲线上的简单远期</strong>成立，但计价物若换成 OIS 零息，远期测度不再使 IBOR 远期为鞅，基差变成额外状态。把 1997 年的漂移原样接到「OIS 贴现的 SOFR 期限远期」上，必须声明计价物与 \\(L_i\\) 的定义一致，见 <a href="/quant/sofr-transition">SOFR 过渡</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>经济内容是凸性：更远的简单远期，其对应的零息债久期更长，为保持折现债券在选定计价物下为鞅，必须在即期测度下补上正的补偿漂移（通常符号约定下）。波动越大、相关越正、中间 \\(L_j\\) 越高，补偿越大。这与瞬时 HJM 的 \\(\\sigma_f\\int\\sigma_f\\) 漂移是同一件事：LMM 把积分换成沿 tenor 的离散求和，并把瞬时波动换成简单利率的百分比波动。</p>',32)),(i(),_(o,null,{default:t(()=>[m(r,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20Far%5B%22%E6%9B%B4%E8%BF%9C%E7%9A%84%20L_i%22%5D%20--%3E%20Dur%5B%22%E5%AF%B9%E5%BA%94%E9%9B%B6%E6%81%AF%E5%80%BA%E4%B9%85%E6%9C%9F%E6%9B%B4%E9%95%BF%22%5D%0A%20%20Dur%20--%3E%20Need%5B%22%E6%8A%98%E7%8E%B0%E5%80%BA%E5%88%B8%E5%9C%A8%E5%8D%B3%E6%9C%9F%E6%B5%8B%E5%BA%A6%E4%B8%8B%E5%81%8F%E7%A6%BB%E9%9E%85%22%5D%0A%20%20Need%20--%3E%20Comp%5B%22%E8%A1%A5%E6%AD%A3%E6%BC%82%E7%A7%BB%3A%20%CF%84_j%20L_j%20%2F%20(1%2B%CF%84_j%20L_j)%20%E9%A1%B9%22%5D%0A%20%20Vol%5B%22%E6%B3%A2%E5%8A%A8%20%CF%83%20%E8%B6%8A%E5%A4%A7%22%5D%20--%3E%20Comp%0A%20%20Cor%5B%22%E7%9B%B8%E5%85%B3%20%CF%81%20%E8%B6%8A%E6%AD%A3%22%5D%20--%3E%20Comp%0A%20%20Mid%5B%22%E4%B8%AD%E9%97%B4%20L_j%20%E8%B6%8A%E9%AB%98%22%5D%20--%3E%20Comp%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p>测度选择不改变套利价格，只改变方差与离散误差。即期测度对整条曲线一次性模拟最自然，漂移项最多；终端测度让长端稳、短端漂移复杂；对每个 caplet 分别用自己的远期测度，解析最干净，却无法给依赖整条曲线的 Bermudan 一次抽样。CMS 要的 \\(\\mathbb{E}^{T_p}[S_T]\\) 既不是即期也不是年金，复制积分其实是在用香草把这次测度变换的凸性买回来，见 <a href="/quant/cms-replication">CMS 复制</a>。</p><p><span class="marginnote">风险中性测度（连续复利银行账户）下的 LMM 漂移还要加上相对滚动 LIBOR 账户的核，不能把即期 LIBOR 测度的 \\(\\mu_i\\) 抄进 \\(\\mathrm{d}r\\) 模拟器。混用是长端折现债不再重定价到 \\(P(0,T)\\) 的典型原因。</span></p><h3 id="冻结、rebonato-与「看起来像-black」" tabindex="-1">冻结、Rebonato 与「看起来像 Black」 <a class="header-anchor" href="#冻结、rebonato-与「看起来像-black」" aria-label="Permalink to &quot;冻结、Rebonato 与「看起来像 Black」&quot;">​</a></h3><p>欧式 swaption 在年金测度下是对 \\(S\\) 的看涨，但 \\(S\\) 的波动由 \\(\\partial S/\\partial L_i\\) 与 \\(L\\) 的协方差给出，权重随 \\(L\\) 变，\\(S\\) 不是对数正态。把权重冻在 \\(t=0\\)，得到 Black 近似，市场报价与模型之间最常用的桥。该近似相当于忽略了权重随机性带来的又一次测度/凸性修正。中等波动可用；长尾、高 \\(\\sigma\\)、强时间依赖的 \\(\\sigma_i(t)\\) 应用模拟。Rebonato 把 ATM swaption 方差写成 \\(\\sigma\\) 与 \\(\\rho\\) 的二次型，便于校准，但它是冻结世界里的对象，不能反过来当无套利定义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 \\(\\mathbb{Q}^{T_{i+1}}\\) 下给 \\(L_k\\)（\\(k\\neq i\\)）也设零漂移。不要让 \\(\\rho\\) 的特征值出负再拿去 Cholesky。不要用 caplet 标定的 \\(\\sigma_i\\) 配历史上的满秩相关矩阵：瞬时相关的秩受因子数限制，满秩历史相关通常不正定或不稳定。位移对数正态把 \\(L+\\delta\\) 当对数正态，漂移公式里 \\(L/(1+\\tau L)\\) 要改成对 \\((L+\\delta)\\) 的相应项，漏改会在负利率区把无套利破坏。</p><p>校准上，\\(\\sigma_i(t)\\) 应光滑；把每个 caplet 的 Black 波动当成独立的分段常数，对冲会出现锯齿 vega。LIBOR 停用后，同一套测度语言可以对期限 RFR 远期写出，但期货凸性、在险期限与支付滞后与 1997 年的 3M USD LIBOR 不同，漂移实现要按新合约重推，不能只改名字。</p><p><span class="marginnote">出处的重心是 Brace, Gątarek &amp; Musiela, <em>Mathematical Finance</em>, 1997 的漂移与测度，而不是后来的微笑扩展。Jamshidian（1997）与 Miltersen–Sandmann–Sondermann（1997）应并列为市场模型的同时文献；实现细节（预测器–校正器）是数值文献，不要写进「BGM 定理」。</span></p>',8)),(i(),_(o,null,{default:t(()=>[m(r,{id:"mermaid-108",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUM%5B%22%E9%80%89%E6%8B%A9%E8%AE%A1%E4%BB%B7%E7%89%A9%20N%22%5D%20--%3E%20GIR%5B%22Girsanov%3A%20dW%20%E5%B9%B3%E7%A7%BB%20%CE%BD%22%5D%0A%20%20LI%5B%22L_i%20%3D%20%E5%80%BA%E5%88%B8%E6%AF%94%22%5D%20--%3E%20FWD%5B%22Q%5E%7BT_i%2B1%7D%3A%20L_i%20%E4%B8%BA%E9%9E%85%22%5D%0A%20%20GIR%20--%3E%20FWD%0A%20%20FWD%20--%3E%20SPOT%5B%22%E5%8D%B3%E6%9C%9F%E6%B5%8B%E5%BA%A6%3A%20%E7%B4%AF%E7%A7%AF%20%CE%BC_i%22%5D%0A%20%20FWD%20--%3E%20TERM%5B%22%E7%BB%88%E7%AB%AF%E6%B5%8B%E5%BA%A6%3A%20%E6%9C%80%E8%BF%9C%20L%20%E4%B8%BA%E9%9E%85%22%5D%0A%20%20FWD%20--%3E%20SWP%5B%22%E5%B9%B4%E9%87%91%E6%B5%8B%E5%BA%A6%3A%20S%20%E4%B8%BA%E9%9E%85%22%5D%0A%20%20SPOT%20--%3E%20MC%5B%22%E6%95%B4%E6%9D%A1%E6%9B%B2%E7%BA%BF%20Monte%20Carlo%22%5D%0A%20%20SWP%20--%3E%20CMS%5B%22%E5%86%8D%E6%8D%A2%E5%88%B0%E6%94%AF%E4%BB%98%E6%97%A5%3A%20CMS%20%E5%87%B8%E6%80%A7%22%5D%0A%20%20MC%20--%3E%20PC%5B%22%E5%AF%B9%E6%95%B0%E6%AC%A7%E6%8B%89%20%2B%20%E9%A2%84%E6%B5%8B%E5%99%A8-%E6%A0%A1%E6%AD%A3%E5%99%A8%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每个 \\(L_i\\) 只在 \\(T_{i+1}\\)-远期测度下为鞅；BGM 的对数正态是该测度下的假设，不是全局假设。</li><li>即期测度漂移 \\(\\mu_i=\\sigma_i\\sum_j \\frac{\\tau_j L_j}{1+\\tau_j L_j}\\rho_{ij}\\sigma_j\\) 来自债券比的相对波动，是离散 HJM 条件。</li><li>终端、即期、年金、支付日远期是不同计价物；价格一致，离散误差与方差不同。</li><li>预测器–校正器修正的是状态依赖漂移的欧拉偏差，不是改模型。</li><li>多曲线与 RFR 不取消这套变换，但计价物必须与被模拟的远期定义一致。</li><li>出处：Brace, Gątarek &amp; Musiela, <em>Mathematical Finance</em>, 1997；Jamshidian, <em>Finance and Stochastics</em>, 1997；Miltersen, Sandmann &amp; Sondermann, <em>Journal of Finance</em>, 1997。</li></ul>',2))])}const T=l(E,[["render",p]]);export{M as __pageData,T as default};
